package com.rumitx.app.tak;
import android.app.*;import android.content.*;import android.os.*;import android.net.*;import android.net.wifi.WifiManager;import com.rumitx.app.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Opt-in bridge. Only addressed messages or the named radio room can key RF. */
public final class GeoChatService extends Service {
 private static volatile GeoChatService running;private volatile boolean stopped;private volatile MulticastSocket socket;private WifiManager.MulticastLock multicast;private final ExecutorService writer=Executors.newSingleThreadExecutor();private final Set<String> seen=new LinkedHashSet<>();
 public static boolean enabled(Context c){return TakSettings.enabled(c,"geochat")&&TakSettings.enabled(c,"pli");}
 public static void refresh(Context c){if(enabled(c))c.startForegroundService(new Intent(c,GeoChatService.class));else c.stopService(new Intent(c,GeoChatService.class));}
 public static void forwardIncoming(String sender,String text){GeoChatService s=running;if(s!=null&&!s.stopped&&enabled(s))try{s.writer.execute(()->s.send(GeoChatPacket.incoming(TakSettings.uid(s),sender,text,System.currentTimeMillis())));}catch(java.util.concurrent.RejectedExecutionException ignored){}}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();running=this;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("rumitx_bridge","GeoChat radio bridge",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,243,new Intent(this,MessagingStatusActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);startForeground(243,new Notification.Builder(this,"rumitx_bridge").setSmallIcon(R.drawable.ic_tak_notification).setContentTitle("RumiTX · GeoChat bridge").setContentText("Radio room forwards to DMR "+TakSettings.prefs(this).getString("bridge_peer","")).setContentIntent(open).setOngoing(true).build());new Thread(this::listen,"RumiTX-GeoChat-listen").start();}
 public int onStartCommand(Intent i,int flags,int id){RadioService.start(this);return START_NOT_STICKY;}
 private void status(String s){TakSettings.prefs(this).edit().putString("bridge_status",s).apply();RadioLog.i("RumiTX-GeoChat",s);}
 private NetworkInterface network()throws Exception {ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);if(cap!=null&&(cap.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||cap.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET))){LinkProperties p=cm.getLinkProperties(n);if(p!=null&&p.getInterfaceName()!=null){NetworkInterface ni=NetworkInterface.getByName(p.getInterfaceName());if(ni!=null&&ni.isUp())return ni;}}}throw new java.io.IOException("Connect to local Wi-Fi or Ethernet");}
 private void listen(){while(!stopped&&enabled(this)){try{NetworkInterface ni=network();WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);if(wm!=null){multicast=wm.createMulticastLock("RumiTX GeoChat");multicast.setReferenceCounted(false);multicast.acquire();}MulticastSocket s=new MulticastSocket(null);socket=s;s.setReuseAddress(true);s.bind(new InetSocketAddress(17012));s.setSoTimeout(2000);s.joinGroup(new InetSocketAddress("224.10.10.1",17012),ni);status("GeoChat ready · room RumiTX Radio → DMR "+TakSettings.prefs(this).getString("bridge_peer",""));while(!stopped&&enabled(this)){byte[] bytes=new byte[60000];DatagramPacket p=new DatagramPacket(bytes,bytes.length);try{s.receive(p);}catch(SocketTimeoutException e){continue;}String[] msg;try{msg=GeoChatPacket.outgoing(new String(bytes,0,p.getLength(),StandardCharsets.UTF_8),TakSettings.uid(this));}catch(Exception malformed){continue;}if(msg==null)continue;synchronized(seen){if(!seen.add(msg[0]))continue;if(seen.size()>512)seen.remove(seen.iterator().next());}final String[] event=msg;writer.execute(()->route(event[0],event[1]));}}catch(Exception e){if(!stopped){status("GeoChat waiting: "+e.getMessage());try{Thread.sleep(5000);}catch(InterruptedException ignored){}}}finally{if(socket!=null)socket.close();socket=null;if(multicast!=null&&multicast.isHeld())multicast.release();}}if(!stopped)stopSelf();}
 private void route(String uid,String text){if(stopped||!enabled(this))return;String peer=TakSettings.prefs(this).getString("bridge_peer","");try(MessageStore store=new MessageStore(this)){if(!store.claimGeoChat(uid))return;long row=store.add(peer,text,"out","GeoChat → radio: sending");String result;try{result=RadioController.getInstance().sendSms(peer,text)?"Module accepted · GeoChat delivery unconfirmed":"GeoChat: no radio acknowledgement";}catch(Exception e){result="GeoChat failed: "+e.getMessage();}store.status(row,result);status(result);}}
 private void send(String xml){if(stopped||!enabled(this))return;try(MulticastSocket s=new MulticastSocket()){s.setTimeToLive(1);s.setNetworkInterface(network());byte[] bytes=xml.getBytes(StandardCharsets.UTF_8);s.send(new DatagramPacket(bytes,bytes.length,InetAddress.getByName("224.10.10.1"),17012));status("DMR text forwarded to GeoChat · receipt unconfirmed");}catch(Exception e){status("GeoChat forwarding failed: "+e.getMessage());}}
 public void onDestroy(){stopped=true;running=null;if(socket!=null)socket.close();writer.shutdown();if(multicast!=null&&multicast.isHeld())multicast.release();stopForeground(true);super.onDestroy();}
}
